import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial, texture } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  // Create plane geometry
  const geometry = new THREE.PlaneGeometry(1, 1);

  // Load texture
  const imageUrl = config.assetUrls?.imageUrl;
  const tex = imageUrl ? ctx.textureLoader(imageUrl) : null;

  // Create material with TSL
  const materialConfig = { transparent: true };
  if (tex) materialConfig.colorNode = texture(tex);
  const material = new MeshBasicNodeMaterial(materialConfig);

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Apply scene placement
  const pos = config.scenePosition || {};
  const rot = config.sceneRotation || {};
  const scale = config.sceneScale || {};

  mesh.position.set(pos.x ?? 0, pos.y ?? 0, pos.z ?? 0);
  mesh.rotation.set(rot.x ?? 0, rot.y ?? 0, rot.z ?? 0);
  mesh.scale.set(scale.x ?? 1, scale.y ?? 1, scale.z ?? 1);

  // Store original transforms
  const origPos = mesh.position.clone();
  const origScale = mesh.scale.clone();

  // Initialize event handlers
  mesh.userData.handlers = {};
  const timelines = [];
  let currentHoverTl = null;

  // Hover enter: rise-in animation (0.15 units up, 0.7s, power3.out)
  mesh.userData.handlers.onPointerEnter = () => {
    if (currentHoverTl) currentHoverTl.kill();

    currentHoverTl = gsap.to(mesh.position, {
      y: origPos.y + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
    timelines.push(currentHoverTl);
  };

  // Hover leave: return to original position
  mesh.userData.handlers.onPointerLeave = () => {
    if (currentHoverTl) currentHoverTl.kill();

    currentHoverTl = gsap.to(mesh.position, {
      y: origPos.y,
      duration: 0.7,
      ease: 'power3.out',
    });
    timelines.push(currentHoverTl);
  };

  // Click: press-down effect (scale 0.97, 120ms, back.out) and emit event
  mesh.userData.handlers.onClick = () => {
    const pressTl = gsap.timeline();
    pressTl.to(mesh.scale, {
      x: origScale.x * 0.97,
      y: origScale.y * 0.97,
      z: origScale.z * 0.97,
      duration: 0.12,
      ease: 'back.out',
    }, 0);
    pressTl.to(mesh.scale, {
      x: origScale.x,
      y: origScale.y,
      z: origScale.z,
      duration: 0.12,
      ease: 'back.out',
    }, 0.12);
    timelines.push(pressTl);

    // Emit event from interaction specification
    const clickInteraction = config.interactions?.find(i => i.event === 'click');
    if (clickInteraction?.effect?.startsWith('emit:')) {
      const eventName = clickInteraction.effect.substring(5);
      mesh.dispatchEvent({ type: eventName });
    }
  };

  // Apply cinematic primitives
  if (config.cinematicPrimitives?.length) {
    config.cinematicPrimitives.forEach(primitive => {
      const primitiveFunc = ctx.primitives?.[primitive.name];
      if (primitiveFunc) {
        primitiveFunc(mesh, primitive.params || {});
      }
    });
  }

  // Cleanup function
  mesh.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    geometry.dispose();
    material.dispose();
  };

  return mesh;
}
